-- México · segunda colección editorial. Tarifas y horarios se dejan vacíos
-- deliberadamente: varían por temporada y deben revisarse en Administración.
ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, department=EXCLUDED.department, category=EXCLUDED.category, description=EXCLUDED.description, latitude=EXCLUDED.latitude, longitude=EXCLUDED.longitude, activities=EXCLUDED.activities, source_url=EXCLUDED.source_url, metadata=EXCLUDED.metadata, updated_at=now();

SELECT id, 'NMD-MX-' || upper(left(replace(slug,'-','_'),30)), 'Sello · ' || name, 'Sello de exploración en México para ' || name, '#C95B3D', true
FROM destinations WHERE country_code='MX'
ON CONFLICT (destination_id) DO NOTHING;
